415	/**
416	 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
417	 *
418	 * Must call (do not reimplement): isEnabled, renderEmail
419	 */
420	import { isEnabled } from "@/lib/feature-flags";
421	import { DIGEST_MAX_ENTRIES } from "@/config/constants";
422	import * as notificationRepo from "@/server/repositories/notification-repository";
423	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
424	import * as orgRepo from "@/server/repositories/organization-repository";
425	import { renderEmail } from "./email-service";
426	import { buildFlagContext } from "./feature-flag-service";
427	import type { RenderedEmail } from "@/server/services/email-service";
