429	import type { User } from "@/types/member";
430	import type { DigestBundle, DigestEntry } from "@/types/notification";
431	
432	/** A digest with fewer entries than this is not worth an email. */
433	const MIN_ENTRIES = 1;
434	
435	/**
436	 * Collects one recipient's unread notifications inside the window. Returns
437	 * `null` — rather than an empty bundle — when the org's plan does not include
438	 * the digest, or when there is nothing to say: the caller treats `null` as
439	 * "send nothing", so a quiet day produces no mail at all.
440	 */
441	export async function buildDigest(
442	  orgId: OrgId,
443	  recipientId: UserId,
444	  windowStart: IsoTimestamp,
445	  windowEnd: IsoTimestamp,
446	): Promise<DigestBundle | null> {
447	  const org = await orgRepo.findOrgById(orgId);
448	  if (!org) return null;
449	
450	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
451	
452	  const unread = await notificationRepo.listUnreadSince(
453	    orgId,
454	    recipientId,
455	    windowStart,
456	  );
457	
458	  const entries: DigestEntry[] = unread
459	    .filter((notification) => notification.createdAt <= windowEnd)
460	    .map((notification) => ({
461	      notificationId: notification.id,
462	      kind: notification.kind,
463	      title: notification.title,
464	      href: notification.href,
465	      occurredAt: notification.createdAt,
466	    }))
467	    .slice(0, DIGEST_MAX_ENTRIES);
468	
469	  if (entries.length < MIN_ENTRIES) return null;
470	
471	  return { orgId, recipientId, entries, windowStart, windowEnd };
472	}
