533	/**
534	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
535	 * no notification logic: it announces the fact, and whoever cares (in-app
536	 * alerts, the digest, webhooks) reacts on the bus.
537	 */
538	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
539	  return runJob("overdue-issues", async (result) => {
540	    if (!shouldFilterArchived(LIVE_ONLY)) {
541	      logger.warn("archive scope misconfigured; skipping sweep", {});
542	      return;
543	    }
544	
545	    const stamp = toIsoTimestamp(now);
546	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
547	
548	    for (const orgId of orgIds) {
549	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
550	
551	      for (const issue of overdue) {
552	        if (issue.dueAt === null) continue;
553	        if (reported.has(issue.id)) continue;
