555	        try {
556	          await emit("issue.overdue", {
557	            orgId,
558	            actorId: null,
559	            occurredAt: stamp,
560	            issueId: issue.id,
561	            projectId: issue.projectId,
562	            dueAt: issue.dueAt,
563	            assigneeId: issue.assigneeId,
564	          });
565	          reported.add(issue.id);
566	          result.processed += 1;
567	        } catch (error) {
568	          result.failed += 1;
569	          logger.error("failed to announce overdue issue", {
570	            issueId: issue.id,
571	            reason: error instanceof Error ? error.message : String(error),
572	          });
573	        }
574	      }
575	    }
576	  });
577	}
