660	/**
661	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
662	 *
663	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
664	 */
665	import { isEnabled } from "@/lib/feature-flags";
666	import { createLogger } from "@/lib/logger";
667	import * as notificationRepo from "@/server/repositories/notification-repository";
668	import * as orgRepo from "@/server/repositories/organization-repository";
669	import * as usageRepo from "@/server/repositories/usage-repository";
670	import * as userRepo from "@/server/repositories/user-repository";
671	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
672	import { sendEmail } from "@/server/services/email-service";
673	import { buildFlagContext } from "@/server/services/feature-flag-service";
674	import { toIsoTimestamp } from "@/types/common";
675	import { runJob } from "./types";
676	import type { JobResult } from "@/server/jobs/types";
