678	
679	const ORG_BATCH = 50;
680	const MS_PER_DAY = 24 * 60 * 60 * 1000;
681	
682	const logger = createLogger("digest-email-job");
683	
684	/**
685	 * One pass per scheduler tick. Each org is only processed during the UTC hour
686	 * it configured, so a tick that runs every few minutes still sends exactly one
687	 * digest per day per recipient.
688	 */
689	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
690	  return runJob("digest-email", async (result) => {
691	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
692	
693	    for (const orgId of orgIds) {
694	      const org = await orgRepo.findOrgById(orgId);
695	      if (!org || !shouldRunForOrg(org, now)) continue;
696	
697	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
698	
699	      const windowEnd = toIsoTimestamp(now);
700	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
701	
702	      for (const recipientId of await listDigestRecipients(orgId)) {
703	        try {
704	          const bundle = await buildDigest(
705	            orgId,
706	            recipientId,
707	            windowStart,
708	            windowEnd,
709	          );
710	          if (!bundle) continue;
711	
712	          const recipient = await userRepo.findUserById(recipientId);
713	          if (!recipient) continue;
714	
715	          const rendered = await renderDigest(bundle, recipient);
716	          await sendEmail({ to: recipient.email, ...rendered });
717	
718	          // Once digested, these notifications are no longer "unread" — this
719	          // is what keeps a later run inside the same window from sending
720	          // the same digest twice.
721	          for (const entry of bundle.entries) {
722	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
723	          }
724	
725	          result.processed += 1;
726	        } catch (error) {
727	          result.failed += 1;
728	          logger.error("digest failed", {
729	            orgId,
730	            recipientId,
731	            reason: error instanceof Error ? error.message : String(error),
732	          });
733	        }
734	      }
735	    }
736	  });
737	}
