770	const logger = createLogger("webhook-delivery-job");
771	
772	/**
773	 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
774	 * corpus builds and runs offline — so "delivery" means computing the
775	 * signature the receiver would verify and logging the attempt. The retry
776	 * bookkeeping around it is the part that has to be right.
777	 */
778	export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
779	  return runJob("webhook-delivery", async (result) => {
780	    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);
781	
782	    for (const delivery of claimed) {
783	      const orgId = delivery.orgId as OrgId;
784	
785	      if (!(await orgAllowsWebhooks(orgId))) {
786	        await webhookRepo.markDeliveryFailed(
787	          orgId,
788	          delivery.id,
789	          "webhooks are not included in this organization's plan",
790	        );
791	        result.failed += 1;
792	        continue;
793	      }
794	
795	      if (delivery.attempts > MAX_ATTEMPTS) {
796	        await webhookRepo.markDeliveryFailed(
797	          orgId,
798	          delivery.id,
799	          `giving up after ${delivery.attempts} attempts`,
800	        );
801	        result.failed += 1;
802	        continue;
803	      }
804	
805	      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
806	        (row) => row.id === delivery.endpointId,
807	      );
808	
809	      if (!endpoint || !endpoint.enabled) {
810	        await webhookRepo.markDeliveryFailed(
811	          orgId,
812	          delivery.id,
813	          "endpoint is missing or disabled",
814	        );
815	        result.failed += 1;
816	        continue;
817	      }
818	
