 * The "is this workspace still open?" guard shared by the service layer.
 *
 * Closing a workspace is final: from that moment nothing in it may be read or
 * written through the app and nothing may be produced on its behalf. Services
 * that take an `Actor` call `assertOrgOpen()` right after `assertOrgScope()`,
 * so an `Actor` minted before the closing is worthless afterwards; background
 * paths that have no actor use `isOrgClosed()` to skip the workspace.
 */
import { isArchived } from "@/lib/soft-delete";
import * as orgRepo from "@/server/repositories/organization-repository";
import { NotFoundError } from "./_support";
import type { OrgId } from "@/types/common";

/** True only for a workspace that exists and has been closed. */
export async function isOrgClosed(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  return org !== null && isArchived(org);
}

/**
 * Throws `not_found` for a closed workspace — the same answer a workspace
 * that never existed gives, so a closed one is indistinguishable from it.
 */
export async function assertOrgOpen(orgId: OrgId): Promise<void> {
  if (await isOrgClosed(orgId)) {
    throw new NotFoundError("Organization", orgId);
  }
}
EOF
for f in usage-service search-service project-service label-service member-service activity-service issue-service billing-service attachment-service invitation-service comment-service webhook-service notification-service organization-service; do
  perl -0pi -e 's/^(  assertOrgScope\(actor, ([\w.]+)\);\n)/$1  await assertOrgOpen($2);\n/mg; s/(\nimport [^\n]*"\.\/_support";\n)/$1import { assertOrgOpen } from ".\/_org-guard";\n/ ' $f.ts
  grep -c "assertOrgOpen" $f.ts
done; grep -L '_org-guard' usage-service.ts search-service.ts project-service.ts label-service.ts member-service.ts activity-service.ts issue-service.ts billing-service.ts attachment-service.ts invitation-service.ts comment-service.ts webhook-service.ts notification-service.ts organization-service.ts
# list exported actor-taking functions lacking the guard
for f in *-service.ts; do awk -v F=$f '/^export (async )?function/{name=$0; has=0; pending=1} /assertOrgOpen/{has=1} /^}/{ if(pending && !has) print F": "name; pending=0 }' $f; done

