python3 - <<'EOF'
p='src/actions/organizations/delete-organization.ts'
s=open(p).read()
old='''export async function deleteOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}'''
new='''/**
 * A closed organization resolves no `Actor`, so a second submit from a stale
 * tab would otherwise surface as "not a member". Someone who was allowed to
 * close it is told what actually happened: it is already closed, a conflict.
 * Everybody else falls through to the normal path and learns nothing.
 */
async function alreadyClosedBy(raw: unknown): Promise<boolean> {
  const parsed = deleteOrganizationSchema.safeParse(raw);
  if (!parsed.success) return false;

  const org = await findOrgById(parsed.data.orgId);
  if (org === null || !isArchived(org)) return false;

  const principal = await getSessionPrincipal();
  if (principal === null) return false;

  const member = await findMember(org.id, principal.userId);
  if (member === null || member.status !== "active") return false;

  return can(
    { userId: principal.userId, orgId: org.id, role: member.role },
    "org:delete",
    { kind: "organization", orgId: org.id },
  );
}

export async function deleteOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  try {
    if (await alreadyClosedBy(raw)) {
      const { orgId } = deleteOrganizationSchema.parse(raw);
      return toActionResult(new AlreadyArchivedError("Organization", orgId));
    }
  } catch (error) {
    return toActionResult(error);
  }

  return run(raw);
}'''
assert old in s
s=s.replace(old,new)
old_imp='import { can } from "@/lib/permissions";\n'
new_imp='''import { toActionResult } from "@/lib/errors";
import { can } from "@/lib/permissions";
import { getSessionPrincipal } from "@/lib/session";
import { AlreadyArchivedError, isArchived } from "@/lib/soft-delete";
'''
assert old_imp in s
s=s.replace(old_imp,new_imp)
old_imp2='import { deleteOrganization } from "@/server/services/organization-service";\n'
assert old_imp2 in s
s=s.replace(old_imp2,'import { findMember } from "@/server/repositories/member-repository";\nimport { findOrgById } from "@/server/repositories/organization-repository";\n'+old_imp2)
open(p,'w').write(s)
EOF
