import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("ROOT/tests/server/_support/doubles/misc")).loggerModule);
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import * as issueService from "@/server/services/issue-service";
import * as invitationService from "@/server/services/invitation-service";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import * as subRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { hashToken } from "@/lib/hash";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, useTemporaryDatabase } from "ROOT/tests/server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("closes", async () => {
  const t = await createTenant("closing", "growth");
  const other = await createTenant("other", "growth");
  await usageRepo.recomputeUsage(t.org.id);
  const ep = await webhookRepo.insertEndpoint({ orgId: t.org.id, url: "https://x.test/h", eventTypes: ["issue.created"] } as never, "s");
  await webhookRepo.enqueueDelivery(t.org.id, ep.id, "issue.created", "{}");
  const ep2 = await webhookRepo.insertEndpoint({ orgId: other.org.id, url: "https://y.test/h", eventTypes: ["issue.created"] } as never, "s");
  await webhookRepo.enqueueDelivery(other.org.id, ep2.id, "issue.created", "{}");
  await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "n@x.test", role: "member", expiresInDays: 14 }, t.userIds.owner, hashToken("tok"));
  const newbie = await userRepo.insertUser({ email: "n@x.test", name: "n", passwordHash: "x" });
  const principal = { userId: t.userIds.member, email: "m", activeOrgId: null, expiresAt: "2999-01-01T00:00:00.000Z" } as never;

  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "wrong" })).rejects.toThrow();
  expect(await sessionService.resolveActorForOrg(principal, "closing")).not.toBeNull();
  await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closing" });
  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closing" })).rejects.toBeInstanceOf(AlreadyArchivedError);

  expect(await sessionService.resolveActorForOrg(principal, "closing")).toBeNull();
  expect(await orgService.resolveOrgBySlug("closing")).toBeNull();
  expect(await orgService.listOrganizationsForUser(t.userIds.member)).toEqual([]);
  await expect(sessionService.switchActiveOrg(principal, { orgId: t.org.id })).rejects.toThrow();
  await expect(issueService.listIssues(t.actors.member, { orgId: t.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
  await expect(invitationService.acceptInvitation(newbie.id, { token: "tok" })).rejects.toThrow();
  expect((await subRepo.findSubscription(t.org.id))?.status).toBe("canceled");
  const r = await runWebhookDeliveryJob(new Date());
  expect(r.processed).toBe(1);
  expect(r.failed).toBe(0);
  expect((await runTrialExpiryJob(new Date("2030-01-01"))).processed).toBe(1);
  expect((await runSearchReindexJob(t.org.id)).processed).toBe(0);
  expect((await usageRepo.listOrgIdsForRollup(50))).not.toContain(t.org.id);
  const again = await orgService.createOrganization(newbie.id, { name: "Closing", slug: "closing", plan: "free" });
  expect(again.slug).toBe("closing-2");
  expect((await orgService.listOrganizationsForUser(other.userIds.member)).length).toBe(1);
});
EOF
